INSERT INTO mcqs (question, option_a, option_b, option_c, option_d, correct_answer, explanation, category, sub_category, topic, difficulty, language, country, exam, tags) VALUES
('What is the normal range of adult blood pressure?', '90/60 - 120/80 mmHg', '120/80 - 140/90 mmHg', '140/90 - 160/100 mmHg', '80/60 - 100/70 mmHg', 'a', 'Normal adult BP is 90/60 to 120/80 mmHg. Hypertension is diagnosed when BP consistently exceeds 140/90 mmHg.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which position is best for a patient with dyspnea?', 'Supine position', 'Fowler''s position', 'Prone position', 'Lithotomy position', 'b', 'Fowler''s position (semi-sitting at 45-90 degrees) facilitates breathing by allowing maximum chest expansion in patients with dyspnea.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the first sign of hypovolemic shock?', 'Bradycardia', 'Increased blood pressure', 'Tachycardia', 'Decreased urine output', 'c', 'Tachycardia is an early compensatory mechanism in hypovolemic shock as the heart attempts to maintain cardiac output.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which medication is used to reverse opioid overdose?', 'Flumazenil', 'Naloxone', 'Atropine', 'Epinephrine', 'b', 'Naloxone (Narcan) is a pure opioid antagonist that reverses respiratory depression caused by opioid overdose.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of fasting blood glucose?', '3.9-6.1 mmol/L', '6.1-7.0 mmol/L', '7.0-11.1 mmol/L', '2.5-3.9 mmol/L', 'a', 'Normal fasting blood glucose is 3.9-6.1 mmol/L (70-110 mg/dL). Values above 7.0 mmol/L indicate diabetes.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which vein is commonly used for IV cannulation?', 'Femoral vein', 'Cephalic vein', 'Popliteal vein', 'Subclavian vein', 'b', 'The cephalic vein in the forearm/hand is the most common site for peripheral IV cannulation due to easy accessibility.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal respiratory rate for adults?', '8-12 breaths/min', '12-20 breaths/min', '20-30 breaths/min', '30-40 breaths/min', 'b', 'Normal adult respiratory rate is 12-20 breaths per minute. Tachypnea is >20, bradypnea is <12.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which food should be avoided in a patient with celiac disease?', 'Rice', 'Wheat', 'Potato', 'Corn', 'b', 'Celiac disease requires a gluten-free diet. Wheat, barley, and rye contain gluten and must be avoided.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common cause of acute pancreatitis?', 'Hyperlipidemia', 'Alcohol consumption', 'Trauma', 'Infection', 'b', 'Alcohol consumption and gallstones are the two most common causes of acute pancreatitis.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which assessment finding indicates deep vein thrombosis?', 'Pallor and coolness', 'Homan''s sign', 'Bounding pulse', 'Decreased sensation', 'b', 'Homan''s sign (calf pain on dorsiflexion of the foot) is a classic sign of DVT, though not always reliable.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the antidote for heparin overdose?', 'Vitamin K', 'Protamine sulfate', 'Naloxone', 'Flumazenil', 'b', 'Protamine sulfate neutralizes heparin by forming a stable salt complex. Vitamin K reverses warfarin.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which stage of pressure ulcer involves full-thickness skin loss?', 'Stage I', 'Stage II', 'Stage III', 'Stage IV', 'c', 'Stage III pressure ulcers involve full-thickness skin loss with damage to subcutaneous tissue but not fascia.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of serum potassium?', '3.5-5.0 mEq/L', '5.0-6.5 mEq/L', '2.0-3.5 mEq/L', '6.5-8.0 mEq/L', 'a', 'Normal serum potassium is 3.5-5.0 mEq/L. Hyperkalemia >5.0, hypokalemia <3.5.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which position is used for administering enema?', 'Supine', 'Prone', 'Left lateral (Sims'')', 'Right lateral', 'c', 'Left lateral (Sims'') position allows gravity to facilitate flow of enema solution into the sigmoid colon.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common nosocomial infection?', 'Surgical site infection', 'Urinary tract infection', 'Pneumonia', 'Bloodstream infection', 'b', 'UTI is the most common healthcare-associated infection, primarily due to indwelling urinary catheters.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which drug is used to treat anaphylactic shock?', 'Diphenhydramine', 'Epinephrine', 'Dopamine', 'Hydrocortisone', 'b', 'Epinephrine (1:1000, 0.3-0.5 mg IM) is the first-line treatment for anaphylaxis due to its vasoconstrictive and bronchodilatory effects.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of hemoglobin in adult males?', '10-12 g/dL', '12-14 g/dL', '13.5-17.5 g/dL', '15-20 g/dL', 'c', 'Normal hemoglobin for adult males is 13.5-17.5 g/dL. For females it is 12.0-15.5 g/dL.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which cranial nerve is tested by asking patient to shrug shoulders?', 'CN IX (Glossopharyngeal)', 'CN X (Vagus)', 'CN XI (Spinal Accessory)', 'CN XII (Hypoglossal)', 'c', 'CN XI (Spinal Accessory) innervates the trapezius and sternocleidomastoid muscles, tested by shoulder shrug and head rotation.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common symptom of myocardial infarction?', 'Epigastric pain', 'Chest pain radiating to left arm', 'Back pain', 'Jaw pain', 'b', 'Classic MI presentation is substernal chest pain/pressure radiating to left arm, neck, or jaw.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which type of isolation is required for tuberculosis?', 'Contact isolation', 'Droplet isolation', 'Airborne isolation', 'Standard precautions', 'c', 'TB requires airborne isolation in a negative pressure room with N95 respirator for healthcare workers.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal INR range for a patient not on anticoagulation?', '0.5-1.0', '0.8-1.2', '1.5-2.5', '2.0-3.0', 'b', 'Normal INR is 0.8-1.2. For patients on warfarin, therapeutic INR is typically 2.0-3.0.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which electrolyte imbalance is most common in burn patients?', 'Hypernatremia', 'Hyperkalemia', 'Hyponatremia', 'Hypocalcemia', 'b', 'Hyperkalemia occurs in burn patients due to cell destruction releasing intracellular potassium into circulation.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the best method to confirm NG tube placement?', 'Auscultation of air', 'pH testing of aspirate', 'X-ray', 'Bubble test', 'c', 'X-ray is the gold standard for confirming NG tube placement. pH testing and auscultation are less reliable.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which vaccine is contraindicated in pregnancy?', 'Tetanus toxoid', 'Hepatitis B', 'MMR (Measles, Mumps, Rubella)', 'Influenza', 'c', 'Live attenuated vaccines like MMR are contraindicated during pregnancy due to risk to the fetus.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common cause of postpartum hemorrhage?', 'Uterine atony', 'Vaginal tear', 'Retained placenta', 'Coagulopathy', 'a', 'Uterine atony (failure of uterus to contract) is the most common cause of postpartum hemorrhage.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which lab value indicates acute kidney injury?', 'BUN 10 mg/dL', 'Creatinine 2.5 mg/dL', 'GFR 120 mL/min', 'BUN/Creatinine ratio 10:1', 'b', 'Elevated creatinine (>1.2 mg/dL) indicates impaired kidney function. AKI is diagnosed by rapid rise in creatinine.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the priority nursing intervention for a patient with chest tube?', 'Clamp chest tube during transport', 'Keep drainage system below chest level', 'Strip tubing every hour', 'Empty drainage every shift', 'b', 'Chest tube drainage system must be kept below chest level to prevent backflow of drainage into pleural space.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which type of shock is characterized by warm, flushed skin?', 'Hypovolemic shock', 'Cardiogenic shock', 'Septic shock (early)', 'Neurogenic shock', 'c', 'Early septic shock presents with warm, flushed skin due to vasodilation. Late septic shock presents with cold, clammy skin.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Hard', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of serum sodium?', '115-125 mEq/L', '125-135 mEq/L', '135-145 mEq/L', '145-155 mEq/L', 'c', 'Normal serum sodium is 135-145 mEq/L. Hyponatremia <135, hypernatremia >145.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which medication is a beta-blocker?', 'Lisinopril', 'Metoprolol', 'Amlodipine', 'Hydrochlorothiazide', 'b', 'Metoprolol is a beta-1 selective blocker used for hypertension, angina, and heart failure.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common complication of diabetes mellitus?', 'Diabetic ketoacidosis', 'Cardiovascular disease', 'Nephropathy', 'Retinopathy', 'b', 'Cardiovascular disease is the leading cause of morbidity and mortality in diabetic patients.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which position is best for post-lumbar puncture?', 'Supine', 'Prone', 'Left lateral', 'Trendelenburg', 'a', 'Supine position for 4-6 hours after lumbar puncture helps prevent post-dural puncture headache.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the Glasgow Coma Scale range?', '1-10', '3-15', '5-20', '0-15', 'b', 'GCS ranges from 3 (deep coma) to 15 (fully awake). It assesses eye, verbal, and motor responses.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which electrolyte is most important for cardiac contractility?', 'Sodium', 'Potassium', 'Calcium', 'Magnesium', 'c', 'Calcium plays a crucial role in cardiac muscle contraction through excitation-contraction coupling.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Hard', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common cause of small bowel obstruction?', 'Tumor', 'Adhesions', 'Hernia', 'Volvulus', 'b', 'Post-surgical adhesions are the most common cause of small bowel obstruction in developed countries.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which blood product requires cross-matching?', 'Fresh frozen plasma', 'Platelets', 'Packed red blood cells', 'Cryoprecipitate', 'c', 'PRBCs require ABO and Rh cross-matching to prevent transfusion reactions.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of serum calcium?', '6.5-8.5 mg/dL', '8.5-10.5 mg/dL', '10.5-12.5 mg/dL', '12.5-14.5 mg/dL', 'b', 'Normal serum calcium is 8.5-10.5 mg/dL. Hypocalcemia <8.5, hypercalcemia >10.5.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which assessment finding indicates increased intracranial pressure?', 'Pinpoint pupils', 'Bradycardia', 'Cushing''s triad', 'Hypotension', 'c', 'Cushing''s triad (hypertension, bradycardia, irregular respirations) indicates increased ICP.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Hard', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common type of stroke?', 'Hemorrhagic', 'Ischemic', 'Embolic', 'Thrombotic', 'b', 'Ischemic stroke accounts for approximately 87% of all strokes. Hemorrhagic stroke accounts for 13%.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which medication is a loop diuretic?', 'Hydrochlorothiazide', 'Spironolactone', 'Furosemide', 'Mannitol', 'c', 'Furosemide (Lasix) is a loop diuretic that acts on the ascending loop of Henle to inhibit sodium reabsorption.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of serum creatinine?', '0.2-0.6 mg/dL', '0.6-1.2 mg/dL', '1.2-2.0 mg/dL', '2.0-3.0 mg/dL', 'b', 'Normal serum creatinine is 0.6-1.2 mg/dL. Elevated levels indicate impaired kidney function.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which position is used for thyroid surgery?', 'Supine with neck extended', 'Fowler''s position', 'Trendelenburg', 'Lithotomy', 'a', 'Supine with neck extended (hyperextended) provides optimal access to the thyroid gland during surgery.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common symptom of urinary tract infection?', 'Fever', 'Dysuria', 'Hematuria', 'Flank pain', 'b', 'Dysuria (painful urination) is the most common symptom of UTI, along with frequency and urgency.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which type of diet is recommended for chronic kidney disease?', 'High protein, high potassium', 'Low protein, low potassium', 'High protein, low sodium', 'Low carbohydrate, high fat', 'b', 'CKD patients need low protein to reduce kidney workload and low potassium to prevent hyperkalemia.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the priority in treating anaphylaxis?', 'Call for help', 'Administer epinephrine', 'Start IV fluids', 'Apply oxygen', 'b', 'Epinephrine is the first-line treatment for anaphylaxis and should be administered immediately.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which cranial nerve is responsible for vision?', 'CN I (Olfactory)', 'CN II (Optic)', 'CN III (Oculomotor)', 'CN IV (Trochlear)', 'b', 'CN II (Optic nerve) is responsible for vision. It is tested using a Snellen chart or visual field examination.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common complication of cirrhosis?', 'Hepatic encephalopathy', 'Portal hypertension', 'Ascites', 'Esophageal varices', 'c', 'Ascites is the most common complication of cirrhosis, caused by portal hypertension and hypoalbuminemia.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which medication is an ACE inhibitor?', 'Metoprolol', 'Lisinopril', 'Amlodipine', 'Losartan', 'b', 'Lisinopril is an ACE inhibitor that blocks the conversion of angiotensin I to angiotensin II.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of serum magnesium?', '1.3-2.1 mEq/L', '2.1-3.0 mEq/L', '3.0-4.0 mEq/L', '0.5-1.3 mEq/L', 'a', 'Normal serum magnesium is 1.3-2.1 mEq/L. Hypomagnesemia <1.3, hypermagnesemia >2.1.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which type of isolation is needed for Clostridium difficile?', 'Airborne', 'Droplet', 'Contact', 'Standard', 'c', 'C. diff requires contact isolation with gloves and gown. Alcohol-based hand sanitizers are ineffective; hand washing with soap and water is required.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common cause of community-acquired pneumonia?', 'Haemophilus influenzae', 'Mycoplasma pneumoniae', 'Streptococcus pneumoniae', 'Chlamydia pneumoniae', 'c', 'Streptococcus pneumoniae is the most common cause of community-acquired pneumonia.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which position is best for a patient with hemorrhoids?', 'Supine', 'Prone', 'Left lateral', 'Knee-chest', 'd', 'Knee-chest position provides best exposure for rectal examination and hemorrhoid treatment.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of WBC count?', '2,000-5,000/mm³', '4,000-11,000/mm³', '11,000-15,000/mm³', '15,000-20,000/mm³', 'b', 'Normal WBC count is 4,000-11,000/mm³. Leukocytosis >11,000 indicates infection or inflammation.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which electrolyte imbalance causes Trousseau''s sign?', 'Hyperkalemia', 'Hypocalcemia', 'Hyponatremia', 'Hypermagnesemia', 'b', 'Trousseau''s sign (carpopedal spasm with BP cuff inflation) indicates hypocalcemia.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Hard', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common type of hernia?', 'Femoral hernia', 'Incisional hernia', 'Inguinal hernia', 'Umbilical hernia', 'c', 'Inguinal hernia is the most common type, accounting for 75% of all abdominal wall hernias.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which medication is used to treat opioid addiction?', 'Naloxone', 'Methadone', 'Flumazenil', 'Naltrexone', 'b', 'Methadone is a long-acting opioid agonist used for maintenance therapy in opioid addiction.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of platelet count?', '50,000-150,000/mm³', '150,000-450,000/mm³', '450,000-750,000/mm³', '750,000-1,000,000/mm³', 'b', 'Normal platelet count is 150,000-450,000/mm³. Thrombocytopenia <150,000 increases bleeding risk.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which assessment finding is most concerning in a post-op patient?', 'Pain 4/10', 'Temperature 37.5°C', 'Urine output 20 mL/hour', 'Heart rate 88 bpm', 'c', 'Urine output <30 mL/hour indicates possible hypovolemia or renal impairment requiring immediate attention.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common cause of hyperthyroidism?', 'Thyroiditis', 'Graves'' disease', 'Toxic nodular goiter', 'Pituitary adenoma', 'b', 'Graves'' disease is the most common cause of hyperthyroidism, an autoimmune disorder stimulating TSH receptors.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which type of shock is caused by pump failure?', 'Hypovolemic', 'Cardiogenic', 'Distributive', 'Obstructive', 'b', 'Cardiogenic shock results from pump failure (e.g., MI, cardiomyopathy) leading to inadequate cardiac output.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of serum bilirubin?', '0.1-0.3 mg/dL', '0.3-1.0 mg/dL', '1.0-2.0 mg/dL', '2.0-3.0 mg/dL', 'b', 'Normal total bilirubin is 0.3-1.0 mg/dL. Jaundice becomes clinically apparent at >2.5 mg/dL.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which position is used for a patient with suspected appendicitis?', 'Supine with legs extended', 'Left lateral with legs flexed', 'Supine with right leg flexed', 'Prone', 'c', 'Patients with appendicitis often lie supine with right hip flexed to relieve tension on the inflamed appendix.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common complication of measles?', 'Encephalitis', 'Pneumonia', 'Otitis media', 'Diarrhea', 'c', 'Otitis media is the most common complication of measles, occurring in 5-15% of cases.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which medication is a calcium channel blocker?', 'Metoprolol', 'Amlodipine', 'Lisinopril', 'Losartan', 'b', 'Amlodipine is a calcium channel blocker that inhibits calcium entry into vascular smooth muscle, causing vasodilation.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the normal range of serum albumin?', '2.5-3.5 g/dL', '3.5-5.0 g/dL', '5.0-6.5 g/dL', '1.5-2.5 g/dL', 'b', 'Normal serum albumin is 3.5-5.0 g/dL. Low albumin indicates malnutrition or liver disease.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('Which type of incontinence is involuntary urine loss with coughing?', 'Urge incontinence', 'Stress incontinence', 'Overflow incontinence', 'Functional incontinence', 'b', 'Stress incontinence is urine leakage with increased intra-abdominal pressure (coughing, sneezing, laughing).', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Easy', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
('What is the most common cause of chronic pancreatitis?', 'Alcohol abuse', 'Gallstones', 'Hypertriglyceridemia', 'Autoimmune', 'a', 'Chronic alcohol abuse is the most common cause of chronic pancreatitis.', 'Nursing', 'Medical Surgical Nursing', 'Medical Surgical Nursing', 'Medium', 'English', 'Bangladesh', 'BPSC Senior Staff Nurse', 'nursing,medical-surgical-nursing'),
