CREATE DATABASE IF NOT EXISTS bpsc_senior_staff_nurse CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bpsc_senior_staff_nurse;

CREATE TABLE IF NOT EXISTS mcqs (
  id BIGINT PRIMARY KEY AUTO_INCREMENT,
  question LONGTEXT NOT NULL,
  option_a TEXT NOT NULL,
  option_b TEXT NOT NULL,
  option_c TEXT NOT NULL,
  option_d TEXT NOT NULL,
  correct_answer CHAR(1) NOT NULL,
  explanation LONGTEXT NOT NULL,
  category VARCHAR(100),
  sub_category VARCHAR(150),
  topic VARCHAR(150),
  difficulty ENUM('Easy','Medium','Hard'),
  language VARCHAR(20),
  country VARCHAR(50),
  exam VARCHAR(100),
  tags TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX idx_mcqs_category ON mcqs(category);
CREATE INDEX idx_mcqs_sub_category ON mcqs(sub_category);
CREATE INDEX idx_mcqs_topic ON mcqs(topic);
CREATE INDEX idx_mcqs_difficulty ON mcqs(difficulty);
CREATE INDEX idx_mcqs_exam ON mcqs(exam);

START TRANSACTION;


COMMIT;
